package com.ranjith.arena.controller;
import com.ranjith.arena.model.*; import com.ranjith.arena.repository.*; import com.ranjith.arena.service.*; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.time.LocalDateTime; import java.util.*;
@RestController @RequestMapping("/api") @CrossOrigin(origins="*") public class ApiController {
 private final UserRepo users; private final ResumeRepo resumes; private final SessionRepo sessions; private final MessageRepo messages; private final EvaluationRepo evaluations; private final ResumeService resumeService; private final InterviewEngine engine; private final EvaluationService evaluationService; private final AiRecruiterService ai;
 public ApiController(UserRepo u,ResumeRepo r,SessionRepo s,MessageRepo m,EvaluationRepo e,ResumeService rs,InterviewEngine ie,EvaluationService es,AiRecruiterService ai){users=u;resumes=r;sessions=s;messages=m;evaluations=e;resumeService=rs;engine=ie;evaluationService=es;this.ai=ai;}
 @GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP","service","AI Interview Arena v6 Genuine AI","aiRecruiter",ai.enabled()?"READY":"NOT_CONFIGURED");}
 @PostMapping("/resume/upload") public ResponseEntity<?> upload(@RequestParam("file") MultipartFile file,@RequestParam(defaultValue="Candidate") String candidateName){try{return ResponseEntity.ok(resumeService.save(file,candidateName));}catch(Exception ex){return ResponseEntity.badRequest().body(Map.of("error","Could not read resume: "+ex.getMessage()));}}
 @GetMapping("/resume/{id}") public ResponseEntity<?> resume(@PathVariable Long id){return resumes.findById(id).map(r->ResponseEntity.ok(Map.of("id",r.getId(),"fileName",r.getFileName(),"candidateName",r.getCandidateName(),"text",r.getExtractedText()))).orElse(ResponseEntity.notFound().build());}
 @PostMapping("/sessions") public ResponseEntity<?> create(@RequestBody Map<String,Object> b){InterviewSession s=new InterviewSession();s.setCandidateName(String.valueOf(b.getOrDefault("candidateName","Candidate")));s.setRole(String.valueOf(b.getOrDefault("role","Java Developer")));s.setInterviewerVoice(String.valueOf(b.getOrDefault("voice","female")));int duration=20;try{duration=Integer.parseInt(String.valueOf(b.getOrDefault("durationMinutes",20)));}catch(Exception ignored){}if(duration<20)duration=20;if(duration>60)duration=60;s.setDurationMinutes(duration);if(b.get("resumeId")!=null)s.setResumeId(Long.valueOf(String.valueOf(b.get("resumeId"))));return ResponseEntity.ok(sessions.save(s));}
 @PostMapping("/sessions/{id}/start") public ResponseEntity<?> start(@PathVariable Long id){return sessions.findById(id).map(s->{s.setStatus("RUNNING");s.setStartedAt(LocalDateTime.now());return ResponseEntity.ok(sessions.save(s));}).orElse(ResponseEntity.notFound().build());}
 @GetMapping("/sessions/{id}/next-question") public ResponseEntity<?> next(@PathVariable Long id,@RequestParam(defaultValue="1") int number){
  var opt=sessions.findById(id); if(opt.isEmpty()) return ResponseEntity.notFound().build(); InterviewSession s=opt.get();
  if(!ai.enabled()) return ResponseEntity.status(503).body(Map.of("error","Genuine AI recruiter is not configured. Set AI_API_URL, AI_API_KEY and AI_MODEL before starting."));
  String resume=s.getResumeId()==null?"":resumes.findById(s.getResumeId()).map(Resume::getExtractedText).orElse("");
  try{ var history=messages.findBySessionIdOrderByCreatedAtAsc(id); var q=ai.nextQuestion(s.getCandidateName(),s.getRole(),resume,history,number); s.setQuestionCount(number); sessions.save(s); InterviewMessage im=new InterviewMessage(); im.setSessionId(id);im.setSpeaker("interviewer");im.setRoundType(q.round());im.setQuestionNumber(number);im.setMessage(q.question());messages.save(im); return ResponseEntity.ok(Map.of("number",number,"round",q.round(),"question",q.question())); }
  catch(Exception ex){return ResponseEntity.status(502).body(Map.of("error",ex.getMessage()));}
 }
 @PostMapping("/sessions/{id}/message") public ResponseEntity<?> message(@PathVariable Long id,@RequestBody Map<String,Object> b){if(!sessions.existsById(id))return ResponseEntity.notFound().build();InterviewMessage m=new InterviewMessage();m.setSessionId(id);m.setSpeaker(String.valueOf(b.getOrDefault("speaker","candidate")));m.setRoundType(String.valueOf(b.getOrDefault("roundType","Technical")));m.setQuestionNumber(Integer.parseInt(String.valueOf(b.getOrDefault("questionNumber",1))));m.setMessage(String.valueOf(b.getOrDefault("message","")));return ResponseEntity.ok(messages.save(m));}
 @GetMapping("/sessions/{id}/messages") public List<InterviewMessage> messages(@PathVariable Long id){return messages.findBySessionIdOrderByCreatedAtAsc(id);}
 @PostMapping("/sessions/{id}/finish") public ResponseEntity<?> finish(@PathVariable Long id){return sessions.findById(id).map(s->{s.setStatus("COMPLETED");s.setEndedAt(LocalDateTime.now());sessions.save(s);return ResponseEntity.ok(evaluationService.evaluate(id));}).orElse(ResponseEntity.notFound().build());}
 @GetMapping("/sessions/{id}/evaluation") public ResponseEntity<?> evaluation(@PathVariable Long id){return evaluations.findBySessionId(id).map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());}
}
